101	// CreateCluster creates a cluster
102	func (db *db) CreateCluster(ctx context.Context, c *appv1.Cluster) (*appv1.Cluster, error) {
103		if c.Server == appv1.KubernetesInternalAPIServerAddr {
104			inClusterEnabled, err := db.settingsMgr.IsInClusterEnabled()
105			if err != nil {
106				log.Warnf(errCheckingInClusterEnabled, "CreateCluster", err)
107			}
108			if !inClusterEnabled {
109				return nil, status.Errorf(codes.InvalidArgument, "cannot register cluster: in-cluster has been disabled")
110			}
111		}
112		secName, err := URIToSecretName("cluster", c.Server)
113		if err != nil {
114			return nil, err
115		}
116	
117		clusterSecret := &corev1.Secret{
118			ObjectMeta: metav1.ObjectMeta{
119				Name: secName,
120			},
121		}
122	
123		err = clusterToSecret(c, clusterSecret)
124		if err != nil {
125			return nil, err
126		}
127	
128		clusterSecret, err = db.createSecret(ctx, clusterSecret)
129		if err != nil {
130			if apierrors.IsAlreadyExists(err) {
131				return nil, status.Errorf(codes.AlreadyExists, "cluster %q already exists", c.Server)
132			}
133			return nil, err
134		}
135	
136		cluster, err := SecretToCluster(clusterSecret)
137		if err != nil {
138			return nil, status.Errorf(codes.InvalidArgument, "could not unmarshal cluster secret %s", clusterSecret.Name)
139		}
140		return cluster, db.settingsMgr.ResyncInformers()
141	}
