	clusterInfo := &appv1.ClusterInfo{
		ConnectionState: appv1.ConnectionState{ModifiedAt: &now},
	}
	if info != nil {
		clusterInfo.ServerVersion = info.K8SVersion
		clusterInfo.APIVersions = argo.APIResourcesToStrings(info.APIResources, true)
		switch {
		case info.LastCacheSyncTime == nil:
			clusterInfo.ConnectionState.Status = appv1.ConnectionStatusUnknown
		case info.SyncError == nil:
			clusterInfo.ConnectionState.Status = appv1.ConnectionStatusSuccessful
			syncTime := metav1.NewTime(*info.LastCacheSyncTime)
			clusterInfo.CacheInfo.LastCacheSyncTime = &syncTime
			clusterInfo.CacheInfo.APIsCount = int64(info.APIsCount)
			clusterInfo.CacheInfo.ResourcesCount = int64(info.ResourcesCount)
		default:
			clusterInfo.ConnectionState.Status = appv1.ConnectionStatusFailed
			clusterInfo.ConnectionState.Message = info.SyncError.Error()
		}
	} else {
		clusterInfo.ConnectionState.Status = appv1.ConnectionStatusUnknown
	}

	updated := c.getUpdatedClusterInfo(ctx, apps, cluster, clusterInfo, now)
	if info == nil && updated.ApplicationsCount == 0 {
		updated.ConnectionState.Message = "Cluster has no applications and is not being monitored."
	}
	return c.cache.SetClusterInfo(cluster.Server, updated)
}

func (c *clusterInfoUpdater) getUpdatedClusterInfo(ctx context.Context, apps []*appv1.Application, cluster appv1.Cluster, clusterInfo *appv1.ClusterInfo, now metav1.Time) *appv1.ClusterInfo {
	var appCount int64
	for _, a := range apps {
		if c.projGetter != nil {
			proj, err := c.projGetter(a)
			if err != nil || !proj.IsAppNamespacePermitted(a, c.namespace) {
				continue
			}
		}
		if c.destinationTargetsCluster(ctx, a.Spec.Destination, cluster) {
			appCount++
		}
	}
	clusterInfo.ApplicationsCount = appCount
	clusterInfo.ConnectionState.ModifiedAt = &now
	return clusterInfo
}

// destinationTargetsCluster reports whether an application destination points at
// the given cluster, either directly via a matching server URL or via a name
// that resolves to the cluster's server URL. A name that resolves to more than
// one server URL is considered ambiguous and never matches.
func (c *clusterInfoUpdater) destinationTargetsCluster(ctx context.Context, dest appv1.ApplicationDestination, cluster appv1.Cluster) bool {
	if dest.Server != "" {
		return dest.Server == cluster.Server
	}
	if dest.Name != "" {
		servers, err := c.db.GetClusterServersByName(ctx, dest.Name)
		if err != nil {
			return false
		}
		// Ambiguous names (resolving to multiple servers) do not count.
		if len(servers) != 1 {
			return false
		}
		return servers[0] == cluster.Server
	}
	return false
